let lookback = 30d;
let Events = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project timestamp, event_name=tostring(name), customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project timestamp, event_name=tostring(message), customDimensions);
Events
| where tostring(customDimensions.telemetry_channel) == "product"
| extend install_id=tostring(customDimensions.install_id), session_id=tostring(customDimensions.session_id)
| summarize active_installs=dcountif(install_id, isnotempty(install_id)), active_sessions=dcountif(session_id, isnotempty(session_id))

let lookback = 30d;
let Events = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project timestamp, event_name=tostring(name), customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project timestamp, event_name=tostring(message), customDimensions);
let started = Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "recording_started" | summarize started_sessions=dcount(tostring(customDimensions.session_id));
let completed = Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "recording_completed" | summarize completed_sessions=dcount(tostring(customDimensions.session_id));
started
| extend completed_sessions=toscalar(completed)
| extend completion_rate_pct=round(100.0 * todouble(completed_sessions) / todouble(started_sessions), 2)

let lookback = 30d;
let Events = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project timestamp, event_name=tostring(name), customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project timestamp, event_name=tostring(message), customDimensions);
let attempted = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "ocr_attempted" | count);
let success = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "ocr_used" | count);
print ocr_attempted=attempted, ocr_success=success, ocr_success_rate_pct=round(100.0 * todouble(success) / todouble(attempted), 2)

let lookback = 30d;
let Events = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project timestamp, event_name=tostring(name), customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project timestamp, event_name=tostring(message), customDimensions);
Events
| where tostring(customDimensions.telemetry_channel) == "product"
| summarize total=count() by event_name
| top 20 by total desc

let lookback = 30d;
let FeatureMap = datatable(event_name:string, feature:string)["snip_started","snip","annotation_committed","annotation","capture_pinned","pin","ocr_used","ocr","recording_started","recording","gif_export_started","gif_export","open_image_used","open_image","beautify_opened","beautify","video_trim_opened","video_trim","settings_opened","settings","about_opened","about"];
let Events = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project event_name=tostring(name), customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project event_name=tostring(message), customDimensions);
let Base = Events
| where tostring(customDimensions.telemetry_channel) == "product"
| extend install_id=tostring(customDimensions.install_id)
| where isnotempty(install_id)
| join kind=inner FeatureMap on event_name;
let TotalInstalls = toscalar(Base | summarize dcount(install_id));
Base
| summarize installs_used=dcount(install_id) by feature
| extend adoption_pct=round(100.0 * todouble(installs_used) / todouble(TotalInstalls), 2)
| order by adoption_pct desc

let lookback = 30d;
let Events = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project event_name=tostring(name), customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project event_name=tostring(message), customDimensions);
let SnipSessions = Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "snip_started" | summarize by session_id=tostring(customDimensions.session_id);
let AnnotateSessions = Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "annotation_committed" | summarize by session_id=tostring(customDimensions.session_id);
let PinSessions = Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "capture_pinned" | summarize by session_id=tostring(customDimensions.session_id);
let snip = toscalar(SnipSessions | count);
let annotate = toscalar(SnipSessions | join kind=inner AnnotateSessions on session_id | count);
let pin = toscalar(SnipSessions | join kind=inner PinSessions on session_id | count);
print snip_sessions=snip, annotate_after_snip=annotate, annotate_rate_pct=round(100.0 * todouble(annotate) / todouble(snip), 2), pin_after_snip=pin, pin_rate_pct=round(100.0 * todouble(pin) / todouble(snip), 2)

let lookback = 90d;
let Events = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project event_name=tostring(name), customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project event_name=tostring(message), customDimensions);
let available = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "update_available" | count);
let confirmed = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "update_confirmed" | count);
let dismissed = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "update_dismissed" | count);
print update_available=available, update_confirmed=confirmed, update_dismissed=dismissed, confirm_rate_pct=round(100.0 * todouble(confirmed) / todouble(available), 2), dismiss_rate_pct=round(100.0 * todouble(dismissed) / todouble(available), 2)

let lookback = 30d;
let Events = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project customDimensions);
let base = Events
| where tostring(customDimensions.telemetry_channel) == "product"
| extend install_id=tostring(customDimensions.install_id), session_id=tostring(customDimensions.session_id);
let installs = toscalar(base | where isnotempty(install_id) | summarize dcount(install_id));
let sessions = toscalar(base | where isnotempty(session_id) | summarize dcount(session_id));
print installs=installs, sessions=sessions, sessions_per_install=round(todouble(sessions) / todouble(installs), 2)

let lookback = 30d;
let Events = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project event_name=tostring(name), customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project event_name=tostring(message), customDimensions);
let errors = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "diagnostic" and event_name == "unhandled_exception" | count);
let sessions = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "product" | summarize dcount(tostring(customDimensions.session_id)));
print unhandled_exceptions=errors, sessions=sessions, exceptions_per_1k_sessions=round(1000.0 * todouble(errors) / todouble(sessions), 2)

let lookback = 30d;
let Events = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project event_name=tostring(name), customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project event_name=tostring(message), customDimensions);
let missing_count = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "diagnostic" and event_name == "ffmpeg_missing" | count);
let recording_starts = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "recording_started" | count);
print ffmpeg_missing=missing_count, recording_starts=recording_starts, missing_per_start_pct=round(100.0 * todouble(missing_count) / todouble(recording_starts), 2)

let lookback = 30d;
let passThreshold = 85.0;
let warnThreshold = 70.0;
let Events = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project event_name=tostring(name), customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project event_name=tostring(message), customDimensions);
let started = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "recording_started" | summarize count());
let completed = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "recording_completed" | summarize count());
let rate = iff(started == 0, real(null), 100.0 * todouble(completed) / todouble(started));
print metric="recording_completion_rate", value_pct=round(rate, 2), started=started, completed=completed, pass_threshold_pct=passThreshold, warn_threshold_pct=warnThreshold
| extend status = case(isnull(value_pct), "NO_DATA", value_pct >= passThreshold, "PASS", value_pct >= warnThreshold, "WARN", "FAIL")

let lookback = 30d;
let passThreshold = 75.0;
let warnThreshold = 60.0;
let Events = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project event_name=tostring(name), customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project event_name=tostring(message), customDimensions);
let attempted = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "ocr_attempted" | summarize count());
let success = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "product" and event_name == "ocr_used" | summarize count());
let rate = iff(attempted == 0, real(null), 100.0 * todouble(success) / todouble(attempted));
print metric="ocr_success_rate", value_pct=round(rate, 2), attempted=attempted, success=success, pass_threshold_pct=passThreshold, warn_threshold_pct=warnThreshold
| extend status = case(isnull(value_pct), "NO_DATA", value_pct >= passThreshold, "PASS", value_pct >= warnThreshold, "WARN", "FAIL")

let lookback = 30d;
let passThreshold = 1.0;
let warnThreshold = 3.0;
let Events = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project event_name=tostring(name), customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project event_name=tostring(message), customDimensions);
let errors = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "diagnostic" and event_name == "unhandled_exception" | summarize count());
let sessions = toscalar(Events | where tostring(customDimensions.telemetry_channel) == "product" | summarize dcount(tostring(customDimensions.session_id)));
let value = iff(sessions == 0, real(null), 1000.0 * todouble(errors) / todouble(sessions));
print metric="exceptions_per_1k_sessions", value_per_1k=round(value, 2), unhandled_exceptions=errors, sessions=sessions, pass_threshold=passThreshold, warn_threshold=warnThreshold
| extend status = case(isnull(value_per_1k), "NO_DATA", value_per_1k <= passThreshold, "PASS", value_per_1k <= warnThreshold, "WARN", "FAIL")

let lookback = 90d;
let passThreshold = 99.5;
let warnThreshold = 98.0;
let Events = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project customDimensions);
let total = toscalar(Events | summarize count());
let missing_count = toscalar(Events | where isempty(tostring(customDimensions.telemetry_channel)) or isempty(tostring(customDimensions.telemetry_schema_version)) | summarize count());
let completeness = iff(total == 0, real(null), 100.0 * (todouble(total - missing_count) / todouble(total)));
print metric="telemetry_schema_completeness", value_pct=round(completeness, 3), total_events=total, missing_schema_or_channel=missing_count, pass_threshold_pct=passThreshold, warn_threshold_pct=warnThreshold
| extend status = case(isnull(value_pct), "NO_DATA", value_pct >= passThreshold, "PASS", value_pct >= warnThreshold, "WARN", "FAIL")

let lookback = 90d;
let Expected = datatable(event_name:string, expected_channel:string)["annotation_committed","product","about_closed","product","about_opened","product","about_url_opened","product","app_closed","product","app_heartbeat","diagnostic","app_started","product","beautify_opened","product","capture_completed","product","capture_delay_used","product","capture_pinned","product","first_capture_completed","product","first_recording_completed","product","ffmpeg_missing","diagnostic","gif_export_completed","product","gif_export_started","product","library_ocr_search_used","product","library_open_used","product","microphone_unavailable","diagnostic","ocr_attempted","product","ocr_no_text","product","ocr_used","product","open_image_used","product","recording_hud_annotation_input_toggled","product","recording_hud_clear_annotations","product","recording_hud_display_mode_changed","product","recording_hud_microphone_toggled","product","recording_hud_pause_toggled","product","recording_hud_stopped","product","recording_hud_tool_selected","product","recording_hud_undo_annotations","product","recording_completed","product","recording_started","product","settings_canceled","product","settings_defaults_restored","product","settings_opened","product","settings_saved","product","settings_section_changed","product","settings_section_reset","product","screenshot_beautified","product","screenshot_beautified_copied","product","snip_cancelled","product","snip_started","product","startup_completed","diagnostic","unhandled_exception","diagnostic","update_available","product","update_check_manual","product","update_confirmed","product","update_dismissed","product","video_trim_completed","product","video_trim_opened","product","video_trim_started","product"];
let Observed = union isfuzzy=true (customEvents | where timestamp > ago(lookback) | project timestamp, event_name=tostring(name), customDimensions), (traces | where timestamp > ago(lookback) and isnotempty(message) | project timestamp, event_name=tostring(message), customDimensions)
| summarize observed_count=count(), last_seen=max(timestamp), observed_channel=any(tostring(customDimensions.telemetry_channel)) by event_name;
Expected
| join kind=fullouter Observed on event_name
| extend expected_channel=coalesce(expected_channel, "n/a")
| extend observed_channel=coalesce(observed_channel, "n/a")
| extend status=case(isnotempty(expected_channel) and expected_channel != "n/a" and observed_count > 0, "Seen", isnotempty(expected_channel) and expected_channel != "n/a" and (isnull(observed_count) or observed_count == 0), "Missing", "Unexpected")
| extend channel_match=case(status == "Seen" and observed_channel == expected_channel, "OK", status == "Seen" and observed_channel != expected_channel, "Mismatch", "n/a")
| project status, event_name, expected_channel, observed_channel, channel_match, observed_count=coalesce(observed_count, 0), last_seen
| order by case(status == "Missing", 0, status == "Unexpected", 1, 2) asc, event_name asc
